"""Unit tests for Agent 7: Report Synthesizer."""
import pytest
from unittest.mock import AsyncMock, patch, MagicMock

from agents.report_synthesizer import report_synthesizer_node, MODEL_NAME

MOCK_REPORT = """---

# RestaurantOS — Company Blueprint
*Generated by FounderAI*

## Executive Summary
RestaurantOS is a cloud-based management platform for Israeli restaurants...

## Market Opportunity
- TAM: $10B global restaurant software
- SAM: $500M Israel + MENA region

## Legal Roadmap
1. Register as חברה בע"מ (2 weeks, ₪2,500)
2. Register for VAT if revenue > ₪100,000/year
3. Open business bank account

## Grants & Funding Opportunities
| Program | Amount | Eligibility | Difficulty | Priority |
|---|---|---|---|---|
| Tnufa | ₪200,000 | Tech startup | Medium | 1st |

## 12-Month Roadmap
- Month 1-2: Legal setup, MVP planning
- Month 3-4: MVP build
- Month 5-6: First customers

## Immediate Next Steps (This Week)
1. Choose company structure (chevra ba'm recommended)
2. Apply for Tnufa grant
3. Define MVP scope
4. Set up development environment
5. Open business bank account

---
*Report generated by FounderAI Multi-Agent Platform*
"""


def _mock_response(text: str):
    msg = MagicMock()
    msg.content = text
    msg.response_metadata = {"token_usage": {"total_tokens": 800}}
    return msg


@pytest.mark.asyncio
async def test_synthesizer_sets_final_report(full_state):
    with patch("agents.report_synthesizer.ChatOpenAI") as MockLLM:
        instance = MockLLM.return_value
        instance.ainvoke = AsyncMock(return_value=_mock_response(MOCK_REPORT))
        result = await report_synthesizer_node(full_state)

    assert result["final_report"] != ""


@pytest.mark.asyncio
async def test_synthesizer_uses_gpt4o():
    """Agent 7 must use gpt-4o — complex synthesis of all prior outputs."""
    assert MODEL_NAME == "gpt-4o"


@pytest.mark.asyncio
async def test_synthesizer_report_has_required_sections(full_state):
    with patch("agents.report_synthesizer.ChatOpenAI") as MockLLM:
        instance = MockLLM.return_value
        instance.ainvoke = AsyncMock(return_value=_mock_response(MOCK_REPORT))
        result = await report_synthesizer_node(full_state)

    report = result["final_report"]
    assert "Executive Summary" in report
    assert "12-Month Roadmap" in report
    assert "Immediate Next Steps" in report


@pytest.mark.asyncio
async def test_synthesizer_status_done(full_state):
    with patch("agents.report_synthesizer.ChatOpenAI") as MockLLM:
        instance = MockLLM.return_value
        instance.ainvoke = AsyncMock(return_value=_mock_response(MOCK_REPORT))
        result = await report_synthesizer_node(full_state)

    assert result["agent_statuses"]["report_synthesizer"] == "done"


@pytest.mark.asyncio
async def test_synthesizer_uses_summarized_inputs(full_state):
    """Verify that the synthesizer truncates prior outputs (token efficiency)."""
    captured = []

    async def capture(messages):
        captured.extend(messages)
        return _mock_response(MOCK_REPORT)

    with patch("agents.report_synthesizer.ChatOpenAI") as MockLLM:
        instance = MockLLM.return_value
        instance.ainvoke = capture
        await report_synthesizer_node(full_state)

    human_msg = captured[-1].content
    # Each section should be at most 1500 chars — total context < 12k chars
    assert len(human_msg) < 15000


@pytest.mark.asyncio
async def test_synthesizer_handles_error(full_state):
    with patch("agents.report_synthesizer.ChatOpenAI") as MockLLM:
        instance = MockLLM.return_value
        instance.ainvoke = AsyncMock(side_effect=Exception("context length exceeded"))
        with pytest.raises(Exception, match="context length exceeded"):
            await report_synthesizer_node(full_state)

    assert full_state["agent_statuses"]["report_synthesizer"] == "error"
